// Do not edit by hand: retake the feature and run it again.
// One entry per Built or Configure feature: the screen that does it, and how
// a person does it, step by step. Gap features have no entry.

export interface FeatureShot {
  file: string;
  title: string;
  alt: string;
}

export interface FeatureGuide {
  shots: FeatureShot[];
  /** Who does it, e.g. "Golf shop staff". */
  who: string;
  steps: string[];
  /** What the person sees when it worked. */
  result: string;
}

/** Served from a folder that robots and AI crawlers are kept out of (see src/proxy.ts). */
export function guideSrc(file: string) {
  return `/images/club-steward/${file}`;
}

